import * as sliderMachine from "@zag-js/slider";
import type { MachineInput } from "marko-zag";
import { cn } from "../../../lib/utils.ts";
import { stripOwnProps } from "../../../lib/native-attrs.ts";

export type Input = MachineInput<"div", sliderMachine.Props> & {
  valueChange?: (value: number[]) => void;
};

<machine-props/machineProps from=input pick=sliderMachine.props
  onValueChange(details: sliderMachine.ValueChangeDetails) {
    input.onValueChange?.(details);
    input.valueChange?.(details.value);
  }/>
<service/service machine=() => sliderMachine.machine props=machineProps/>
<connect/api=(service, normalizeProps) =>
  sliderMachine.connect(service, normalizeProps)
  service=service
/>

<const/nativeAttrs=() =>
  stripOwnProps(sliderMachine.splitProps(input)[1], "class", "valueChange")
>

<div
  ...nativeAttrs()
  ...api().getRootProps()
  data-slot="slider"
  class=cn("data-vertical:min-h-40 relative flex w-full touch-none items-center select-none data-[disabled]:opacity-50 data-[orientation=vertical]:h-full data-[orientation=vertical]:w-auto data-[orientation=vertical]:flex-col", input.class)
>
  // zag-required control wrapper (no upstream counterpart; style CSS never
  // targets it). Mirrors the root's orientation utilities so vertical works
  // through the extra layer.
  <div ...api().getControlProps() data-slot="slider-control" class="relative flex grow touch-none items-center select-none data-[orientation=vertical]:h-full data-[orientation=vertical]:flex-col">
    <div ...api().getTrackProps() data-slot="slider-track" class="bg-muted rounded-4xl data-horizontal:h-3 data-horizontal:w-full data-vertical:h-full data-vertical:w-3 relative grow overflow-hidden data-[orientation=horizontal]:w-full data-[orientation=vertical]:h-full">
      <div ...api().getRangeProps() data-slot="slider-range" class="bg-primary absolute select-none data-[orientation=horizontal]:h-full data-[orientation=vertical]:w-full"></div>
    </div>
    <for|_, i| of=api().value>
      <input ...api().getHiddenInputProps({ index: i })>
      <div ...api().getThumbProps({ index: i }) data-slot="slider-thumb" class="border-primary ring-ring/50 size-4 rounded-4xl border bg-white shadow-sm transition-colors hover:ring-4 focus-visible:ring-4 focus-visible:outline-hidden block shrink-0 select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50"></div>
    </for>
  </div>
</div>

<return=api>
